
import type { Context } from "hono";
import type { DB, DbSchema, Dialect } from "./db";
import type { Role } from "@shared/types";

/**
 * Runtime bindings. `Env` is generated by `wrangler types`
 * (worker-configuration.d.ts) and contains the active Cloudflare bindings.
 * R2 is intentionally not configured for this deployment.
 */
export interface AppBindings extends Env {
  SESSION_SECRET: string;

  /** One-time bootstrap token gating the first-run installer (`POST /api/setup`). */
  SETUP_TOKEN: string;

  /**
   * NOTE: PBKDF2_ITERATIONS is a wrangler var and is already
   * included in the generated Env. It is intentionally NOT redeclared.
   */

  /**
   * Hyperdrive (Postgres) binding, present only when DB_DRIVER="postgres"
   * and the hyperdrive block in wrangler.jsonc is configured.
   */
  HYPERDRIVE?: Hyperdrive;

  /**
   * RATE_LIMITER is generated from the Wrangler Durable Object binding.
   * It is treated as optional at runtime by worker/lib/ratelimit.ts.
   */
}

export interface SessionUser {
  id: string;
  email: string;
  role: Role;
}

export interface AppVariables {
  db: DB;
  schema: DbSchema;
  dialect: Dialect;
  user: SessionUser | null;
  sessionId: string | null;
}

export type AppEnv = {
  Bindings: AppBindings;
  Variables: AppVariables;
};

export type AppContext = Context<AppEnv>;
